 rel='source/wlan/openmitrastar_rbsdfs_kernel.inc';path=a.output/rel;s=path.read_text();s=s.replace('c->result=s->provider->open_window(s->provider->frame.context,c->role,c->channel,c->deadline);','c->result=s->provider->open_window(s->provider->frame.context,c->role,c->channel,c->deadline);',1);path.write_text(s,newline='\n');changes[rel]=sha(path)
 r.update(status='SOURCE_ONLY_RBS466468_KERNEL_TYPED_CAC_CAPTURE_EXIT_REFUSAL_PENDING',parent_revision=str(a.parent),parent_revision_sha256=sha(a.parent/'result.json'),changed_sources=changes,revision='r2',captured_pre_stop_cac_mbs_propagated=True,outerexit_retainedframe_refuses=True,missing=[x for x in r['missing']if not x.startswith('MBSproducer capturedpreCAC')]+['CompleteactualMBS/RBSreportframecaller/OEMfunctionequivalence remainsunqualified']);(a.output/'result.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps({k:v for k,v in r.items()if k not in('changed_sources','input_pins')}))
